<div class="hkp-head"><div><h1><?php echo hkp_e('Action plans'); ?></h1><p><?php echo hkp_e('Review submitted evidence and close the loop with a reassessment.'); ?></p></div>
<div class="hkp-tabs" style="margin:0;border:0"><?php foreach (array('' => 'All', 'submitted' => 'Submitted', 'overdue' => 'Overdue', 'assigned' => 'Assigned', 'completed' => 'Completed') as $k => $l): ?><a href="?status=<?php echo $k; ?>" class="<?php echo (string) $st === (string) $k ? 'is-active' : ''; ?>"><?php echo hkp_e($l); ?></a><?php endforeach; ?></div></div>
<section class="hkp-card"><?php if (!$rows): ?><div class="hkp-empty"><?php echo hkp_e('No action plans.'); ?></div><?php endif; ?>
<div class="hkp-table-wrap"><table class="hkp-table"><thead><tr><th><?php echo hkp_e('Employee'); ?></th><th><?php echo hkp_e('Action'); ?></th><th><?php echo hkp_e('Competency'); ?></th><th><?php echo hkp_e('Priority'); ?></th><th><?php echo hkp_e('Due'); ?></th><th><?php echo hkp_e('Status'); ?></th></tr></thead><tbody>
<?php foreach ($rows as $a): ?><tr><td><?php echo hkp_person_open($a['user_id']); ?><?php echo hkp_h($a['first_name'] . ' ' . $a['last_name']); ?><?php echo hkp_person_close(); ?></td><td><a href="<?php echo hkp_url('actions/view/' . $a['id']); ?>"><?php echo hkp_h($a['title']); ?></a></td><td class="hkp-small"><?php echo hkp_h(hkp_pick($a, 'skill')); ?></td><td><?php echo hkp_badge($a['priority']); ?></td><td class="hkp-small"><?php echo hkp_date($a['due_at']); ?></td><td><?php echo hkp_badge($a['status']); ?></td></tr><?php endforeach; ?>
</tbody></table></div></section>
